selector_to_html = {"a[href=\"#modular-documentation-build-system\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Modular Documentation Build System<a class=\"headerlink\" href=\"#modular-documentation-build-system\" title=\"Link to this heading\">#</a></h1><p>This directory contains the modular documentation build system for Haive, which allows building package-specific documentation with customized extension profiles.</p>", "a[href=\"#creating-a-new-package-profile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Creating a New Package Profile<a class=\"headerlink\" href=\"#creating-a-new-package-profile\" title=\"Link to this heading\">#</a></h3><p>Add a new function in <code class=\"docutils literal notranslate\"><span class=\"pre\">package_configs.py</span></code>:</p>", "a[href=\"#troubleshooting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Troubleshooting<a class=\"headerlink\" href=\"#troubleshooting\" title=\"Link to this heading\">#</a></h2><h3>Extension Not Available<a class=\"headerlink\" href=\"#extension-not-available\" title=\"Link to this heading\">#</a></h3><p>If you see warnings about extensions not being available:</p>", "a[href=\"#extension-not-available\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Extension Not Available<a class=\"headerlink\" href=\"#extension-not-available\" title=\"Link to this heading\">#</a></h3><p>If you see warnings about extensions not being available:</p>", "a[href=\"#quick-development-builds\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Development Builds<a class=\"headerlink\" href=\"#quick-development-builds\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#customization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Customization<a class=\"headerlink\" href=\"#customization\" title=\"Link to this heading\">#</a></h2><h3>Adding Extensions to a Profile<a class=\"headerlink\" href=\"#adding-extensions-to-a-profile\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">package_configs.py</span></code>:</p>", "a[href=\"#build-failures\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Build Failures<a class=\"headerlink\" href=\"#build-failures\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#mcp-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MCP Package<a class=\"headerlink\" href=\"#mcp-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#games-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Games Package<a class=\"headerlink\" href=\"#games-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#list-available-profiles\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">List Available Profiles<a class=\"headerlink\" href=\"#list-available-profiles\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#build-documentation-for-a-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Build Documentation for a Package<a class=\"headerlink\" href=\"#build-documentation-for-a-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#usage\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Usage<a class=\"headerlink\" href=\"#usage\" title=\"Link to this heading\">#</a></h2><h3>Build Documentation for a Package<a class=\"headerlink\" href=\"#build-documentation-for-a-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#adding-extensions-to-a-profile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Adding Extensions to a Profile<a class=\"headerlink\" href=\"#adding-extensions-to-a-profile\" title=\"Link to this heading\">#</a></h3><p>Edit <code class=\"docutils literal notranslate\"><span class=\"pre\">package_configs.py</span></code>:</p>", "a[href=\"#core-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Core Package<a class=\"headerlink\" href=\"#core-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>The modular build system provides:</p>", "a[href=\"#test-the-system\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Test the System<a class=\"headerlink\" href=\"#test-the-system\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#package-configs-py\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. <code class=\"docutils literal notranslate\"><span class=\"pre\">package_configs.py</span></code><a class=\"headerlink\" href=\"#package-configs-py\" title=\"Link to this heading\">#</a></h3><p>Defines extension profiles for each package:</p>", "a[href=\"#noxfiles-session-docs-modular-py\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. <code class=\"docutils literal notranslate\"><span class=\"pre\">noxfiles/session_docs_modular.py</span></code><a class=\"headerlink\" href=\"#noxfiles-session-docs-modular-py\" title=\"Link to this heading\">#</a></h3><p>Nox sessions for building documentation:</p>", "a[href=\"#compare-profiles\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Compare Profiles<a class=\"headerlink\" href=\"#compare-profiles\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#import-errors\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Import Errors<a class=\"headerlink\" href=\"#import-errors\" title=\"Link to this heading\">#</a></h3><p>Ensure you\u2019re running from the project root or that PYTHONPATH includes the conf_modules directory.</p>", "a[href=\"#future-enhancements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Future Enhancements<a class=\"headerlink\" href=\"#future-enhancements\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#components\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Components<a class=\"headerlink\" href=\"#components\" title=\"Link to this heading\">#</a></h2><h3>1. <code class=\"docutils literal notranslate\"><span class=\"pre\">package_configs.py</span></code><a class=\"headerlink\" href=\"#package-configs-py\" title=\"Link to this heading\">#</a></h3><p>Defines extension profiles for each package:</p>", "a[href=\"#modular-builder-py\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. <code class=\"docutils literal notranslate\"><span class=\"pre\">modular_builder.py</span></code><a class=\"headerlink\" href=\"#modular-builder-py\" title=\"Link to this heading\">#</a></h3><p>The build logic that:</p>", "a[href=\"#extension-profiles\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Extension Profiles<a class=\"headerlink\" href=\"#extension-profiles\" title=\"Link to this heading\">#</a></h2><h3>Core Package<a class=\"headerlink\" href=\"#core-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#dataflow-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Dataflow Package<a class=\"headerlink\" href=\"#dataflow-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#prebuilt-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Prebuilt Package<a class=\"headerlink\" href=\"#prebuilt-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#agents-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Agents Package<a class=\"headerlink\" href=\"#agents-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tools-package\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Tools Package<a class=\"headerlink\" href=\"#tools-package\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#performance-considerations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Performance Considerations<a class=\"headerlink\" href=\"#performance-considerations\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
